Set<Id> ids=new Set<Id>{a.Id,b.Id};
Set<Id> accountScope=new Set<Id>{a.Id,b.Id,c.Id};
Set<Id> contactScope=new Set<Id>{ca.Id,cb.Id,cc.Id,loose.Id};
Integer l=1,o=1;
v.put('phase','query');List<SObject> selected=Database.query('SELECT Id,LastName FROM Contact WHERE Id IN :contactScope AND AccountId IN (SELECT Id FROM Account WHERE Id IN :ids)');Integer outOfScope=0;List<String> keys=new List<String>();List<String> children=new List<String>();for(SObject item:selected){if(!contactScope.contains(item.Id)){outOfScope++;continue;}String key=String.valueOf(item.get('LastName'));if(item.Id==a.Id){key='SJ-Aster';}else if(item.Id==b.Id){key='SJ-Birch';}else if(item.Id==c.Id){key='SJ-Cedar';}keys.add(key);}keys.sort();children.sort();v.put('rows',selected.size());v.put('keys',keys);v.put('outOfScope',outOfScope);}catch(Exception e){v.put('exceptionType',e.getTypeName());v.put('exceptionMessage',e.getMessage());}System.assert(false,'C157_RESULT|C157SJ_007|'+JSON.serialize(v));

